import { z } from "zod";
import { EventConfig, Handlers } from "motia";
import { WebClient } from "@slack/web-api";

const ActionExecutorInputSchema = z.object({
  submissionId: z.string(),
  decision: z.enum(["approved", "rejected", "escalated"]),
  reviewedBy: z.string(),
  reviewedAt: z.string(),
  channel: z.string(),
  messageTs: z.string(),
  reason: z.string().optional(),
});

export const config: EventConfig = {
  type: "event",
  name: "ActionExecutor",
  description: "Executes final actions based on moderation decisions",
  subscribes: ["content.reviewed"],
  emits: [],
  input: ActionExecutorInputSchema,
  flows: ["content-moderation"],
};

// Initialize Slack client
const web = new WebClient(process.env.SLACK_BOT_TOKEN);

export const handler: Handlers["ActionExecutor"] = async (
  input,
  { logger, state }
) => {
  const {
    submissionId,
    decision,
    reviewedBy,
    reviewedAt,
    channel,
    messageTs,
    reason,
  } = input;

  logger.info("Executing final action", { submissionId, decision, reviewedBy });

  try {
    // Get the full submission data
    const submission = await state.get(
      "moderation",
      `submission:${submissionId}`
    );
    if (!submission) {
      logger.error("Submission not found for final action", { submissionId });
      return;
    }

    // Execute the actual content action based on decision
    await executeContentAction(submission, decision, logger);

    // Update Slack message with final status
    await updateSlackMessage(
      channel,
      messageTs,
      submission,
      decision,
      reviewedBy,
      reviewedAt
    );

    // Update final state
    await state.set("moderation", `submission:${submissionId}`, {
      ...submission,
      status: "completed",
      finalDecision: decision,
      executedAt: new Date().toISOString(),
      completedBy: reviewedBy,
    });

    // Send completion notification if escalated
    if (decision === "escalated") {
      await sendEscalationNotification(submission, reviewedBy, channel);
    }

    logger.info("Content moderation workflow completed", {
      submissionId,
      decision,
      reviewedBy,
      workflow: "success",
    });
  } catch (error) {
    logger.error("Failed to execute final action", {
      submissionId,
      decision,
      error: error instanceof Error ? error.message : "Unknown error",
    });

    // Mark as failed in state
    await state.set("moderation", `submission:${submissionId}`, {
      submissionId,
      status: "execution_failed",
      error: error instanceof Error ? error.message : "Unknown error",
      failedAt: new Date().toISOString(),
    });
  }
};

async function executeContentAction(
  submission: any,
  decision: string,
  logger: any
) {
  // In a real implementation, this would:
  // - Publish approved content to your platform
  // - Block/delete rejected content
  // - Move escalated content to senior review queue

  const { submissionId, userId, text, imageUrl, platform } = submission;

  switch (decision) {
    case "approved":
      logger.info("Publishing content", { submissionId, userId, platform });
      // TODO: Implement actual content publishing logic
      // Example: await contentService.publish({ submissionId, text, imageUrl, userId });
      break;

    case "rejected":
      logger.info("Blocking content", { submissionId, userId, platform });
      // TODO: Implement actual content blocking logic
      // Example: await contentService.block({ submissionId, userId, reason: 'Policy violation' });
      break;

    case "escalated":
      logger.info("Escalating content for senior review", {
        submissionId,
        userId,
        platform,
      });
      // TODO: Implement escalation logic
      // Example: await seniorReviewService.add({ submissionId, originalReviewer, priority: 'high' });
      break;

    default:
      logger.warn("Unknown decision type", { decision, submissionId });
  }
}

async function updateSlackMessage(
  channel: string,
  messageTs: string,
  submission: any,
  decision: string,
  reviewedBy: string,
  reviewedAt: string
) {
  const { submissionId, overallScore } = submission;
  const statusEmoji = getStatusEmoji(decision);
  const statusText = getStatusText(decision);

  try {
    await web.chat.update({
      channel,
      ts: messageTs,
      blocks: [
        {
          type: "header",
          text: {
            type: "plain_text",
            text: `${statusEmoji} Content Review - ${statusText}`,
          },
        },
        {
          type: "section",
          fields: [
            {
              type: "mrkdwn",
              text: `*Submission ID:*\n${submissionId}`,
            },
            {
              type: "mrkdwn",
              text: `*Risk Score:*\n${(overallScore * 100).toFixed(1)}%`,
            },
            {
              type: "mrkdwn",
              text: `*Decision:*\n${statusText}`,
            },
            {
              type: "mrkdwn",
              text: `*Reviewed By:*\n@${reviewedBy}`,
            },
          ],
        },
        {
          type: "section",
          text: {
            type: "mrkdwn",
            text: `*Completed:* ${new Date(reviewedAt).toLocaleString()}`,
          },
        },
        {
          type: "context",
          elements: [
            {
              type: "plain_text",
              text: `✅ Action executed successfully`,
            },
          ],
        },
      ],
    });
  } catch (error) {
    // Log but don't fail the whole process if Slack update fails
    console.error("Failed to update Slack message:", error);
  }
}

async function sendEscalationNotification(
  submission: any,
  reviewedBy: string,
  originalChannel: string
) {
  const { submissionId, overallScore, reason } = submission;
  const escalationChannel =
    process.env.SLACK_CHANNEL_ESCALATED || "#content-escalated";

  try {
    await web.chat.postMessage({
      channel: escalationChannel,
      blocks: [
        {
          type: "header",
          text: {
            type: "plain_text",
            text: "🔺 Content Escalated for Senior Review",
          },
        },
        {
          type: "section",
          fields: [
            {
              type: "mrkdwn",
              text: `*Submission ID:*\n${submissionId}`,
            },
            {
              type: "mrkdwn",
              text: `*Risk Score:*\n${(overallScore * 100).toFixed(1)}%`,
            },
            {
              type: "mrkdwn",
              text: `*Escalated By:*\n@${reviewedBy}`,
            },
            {
              type: "mrkdwn",
              text: `*Original Channel:*\n<#${originalChannel}>`,
            },
          ],
        },
        {
          type: "section",
          text: {
            type: "mrkdwn",
            text: `*Reason:* ${reason}`,
          },
        },
        {
          type: "actions",
          elements: [
            {
              type: "button",
              text: {
                type: "plain_text",
                text: "✅ Senior Approve",
              },
              style: "primary",
              value: JSON.stringify({ submissionId, action: "senior_approve" }),
              action_id: "senior_approve",
            },
            {
              type: "button",
              text: {
                type: "plain_text",
                text: "❌ Senior Reject",
              },
              style: "danger",
              value: JSON.stringify({ submissionId, action: "senior_reject" }),
              action_id: "senior_reject",
            },
          ],
        },
      ],
    });
  } catch (error) {
    console.error("Failed to send escalation notification:", error);
  }
}

function getStatusEmoji(decision: string): string {
  switch (decision) {
    case "approved":
      return "✅";
    case "rejected":
      return "❌";
    case "escalated":
      return "🔺";
    default:
      return "❓";
  }
}

function getStatusText(decision: string): string {
  switch (decision) {
    case "approved":
      return "APPROVED";
    case "rejected":
      return "REJECTED";
    case "escalated":
      return "ESCALATED";
    default:
      return "UNKNOWN";
  }
}

/**
 * Gemini Interactions API Service
 * 
 * Unified interface for interacting with Gemini models and agents
 * using the new Interactions API for stateful conversations,
 * function calling, and deep research capabilities.
 * 
 * Note: The Interactions API is in Beta. Types are simplified
 * as the official SDK types may not be fully available yet.
 */

import { GoogleGenAI } from '@google/genai'

// Type definitions for Interactions API (Beta)
type Interaction = any
type InteractionContent = any

export type GeminiModel = 'gemini-3-pro-preview' | 'gemini-2.5-flash' | 'gemini-2.5-pro'
export type GeminiAgent = 'deep-research-pro-preview-12-2025'

export interface InteractionOptions {
  model?: GeminiModel
  agent?: GeminiAgent
  previousInteractionId?: string
  tools?: InteractionTool[]
  responseFormat?: Record<string, unknown>
  generationConfig?: GenerationConfig
  stream?: boolean
  background?: boolean
  store?: boolean
}

export interface InteractionTool {
  type: 'function' | 'google_search' | 'code_execution' | 'url_context' | 'mcp_server'
  name?: string
  description?: string
  parameters?: Record<string, unknown>
  url?: string
}

export interface GenerationConfig {
  temperature?: number
  maxOutputTokens?: number
  thinkingLevel?: 'low' | 'medium' | 'high'
}

export interface FunctionCall {
  id: string
  name: string
  arguments: Record<string, unknown>
}

export interface FunctionResult {
  type: 'function_result'
  name: string
  callId: string
  result: unknown
}

export interface GeminiResponse {
  id: string
  text: string
  status: 'completed' | 'in_progress' | 'requires_action' | 'failed' | 'cancelled'
  functionCalls?: FunctionCall[]
  usage?: {
    promptTokens: number
    completionTokens: number
    totalTokens: number
  }
}

export interface StreamChunk {
  eventType: 'content.delta' | 'interaction.complete'
  delta?: {
    type: 'text' | 'thought'
    text?: string
    thought?: string
  }
  interaction?: Interaction
}

class GeminiInteractionsService {
  private client: GoogleGenAI

  constructor(apiKey?: string) {
    const key = apiKey || process.env.GEMINI_API_KEY
    if (!key) {
      throw new Error('GEMINI_API_KEY is required. Set it as an environment variable or pass it to the constructor.')
    }
    this.client = new GoogleGenAI({ apiKey: key })
  }

  /**
   * Create a new interaction with the Gemini API
   * Supports text, multimodal inputs, function calling, and agents
   */
  async createInteraction(
    input: string | InteractionContent[],
    options: InteractionOptions = {}
  ): Promise<GeminiResponse> {
    const {
      model = 'gemini-3-pro-preview',
      agent,
      previousInteractionId,
      tools,
      responseFormat,
      generationConfig,
      background = false,
      store = true,
    } = options

    const interactionParams: Record<string, unknown> = {
      input,
      store,
    }

    // Use either model or agent, not both
    if (agent) {
      interactionParams.agent = agent
      interactionParams.background = background
    } else {
      interactionParams.model = model
    }

    if (previousInteractionId) {
      interactionParams.previous_interaction_id = previousInteractionId
    }

    if (tools && tools.length > 0) {
      interactionParams.tools = tools
    }

    if (responseFormat) {
      interactionParams.response_format = responseFormat
    }

    if (generationConfig) {
      interactionParams.generation_config = {
        temperature: generationConfig.temperature,
        max_output_tokens: generationConfig.maxOutputTokens,
        thinking_level: generationConfig.thinkingLevel,
      }
    }

    const interaction = await this.client.interactions.create(interactionParams as any)

    return this.mapInteractionToResponse(interaction)
  }

  /**
   * Create a streaming interaction for real-time responses
   */
  async *createStreamingInteraction(
    input: string | InteractionContent[],
    options: Omit<InteractionOptions, 'stream'> = {}
  ): AsyncGenerator<StreamChunk> {
    const {
      model = 'gemini-3-pro-preview',
      previousInteractionId,
      tools,
      responseFormat,
      generationConfig,
    } = options

    const interactionParams: Record<string, unknown> = {
      model,
      input,
      stream: true,
    }

    if (previousInteractionId) {
      interactionParams.previous_interaction_id = previousInteractionId
    }

    if (tools && tools.length > 0) {
      interactionParams.tools = tools
    }

    if (responseFormat) {
      interactionParams.response_format = responseFormat
    }

    if (generationConfig) {
      interactionParams.generation_config = {
        temperature: generationConfig.temperature,
        max_output_tokens: generationConfig.maxOutputTokens,
        thinking_level: generationConfig.thinkingLevel,
      }
    }

    const stream = await this.client.interactions.create(interactionParams as any)

    for await (const chunk of stream as any) {
      yield {
        eventType: chunk.event_type,
        delta: chunk.delta ? {
          type: chunk.delta.type,
          text: chunk.delta.text,
          thought: chunk.delta.thought,
        } : undefined,
        interaction: chunk.interaction,
      }
    }
  }

  /**
   * Continue a conversation by providing function results
   */
  async provideFunctionResults(
    previousInteractionId: string,
    results: FunctionResult[],
    options: Omit<InteractionOptions, 'previousInteractionId'> = {}
  ): Promise<GeminiResponse> {
    const input = results.map(r => ({
      type: 'function_result' as const,
      name: r.name,
      call_id: r.callId,
      result: r.result,
    }))

    return this.createInteraction(input, {
      ...options,
      previousInteractionId,
    })
  }

  /**
   * Get a previously stored interaction by ID
   */
  async getInteraction(interactionId: string): Promise<GeminiResponse> {
    const interaction = await this.client.interactions.get(interactionId)
    return this.mapInteractionToResponse(interaction)
  }

  /**
   * Poll for completion of a background interaction (for agents like Deep Research)
   */
  async pollForCompletion(
    interactionId: string,
    options: {
      pollIntervalMs?: number
      maxWaitMs?: number
      onProgress?: (status: string) => void
    } = {}
  ): Promise<GeminiResponse> {
    const { pollIntervalMs = 10000, maxWaitMs = 600000, onProgress } = options
    const startTime = Date.now()

    while (Date.now() - startTime < maxWaitMs) {
      const interaction = await this.client.interactions.get(interactionId)
      const status = (interaction as any).status

      if (onProgress) {
        onProgress(status)
      }

      if (status === 'completed') {
        return this.mapInteractionToResponse(interaction)
      }

      if (status === 'failed' || status === 'cancelled') {
        throw new Error(`Interaction ${status}: ${interactionId}`)
      }

      await this.sleep(pollIntervalMs)
    }

    throw new Error(`Interaction timed out after ${maxWaitMs}ms: ${interactionId}`)
  }

  /**
   * Create an interaction with structured output (JSON schema)
   */
  async createStructuredInteraction<T>(
    input: string | InteractionContent[],
    schema: Record<string, unknown>,
    options: Omit<InteractionOptions, 'responseFormat'> = {}
  ): Promise<{ id: string; data: T; status: string }> {
    const response = await this.createInteraction(input, {
      ...options,
      responseFormat: schema,
    })

    try {
      // Try to parse the JSON response
      let text = response.text.trim()

      // Handle markdown code blocks if present
      if (text.startsWith('```json')) {
        text = text.slice(7)
      } else if (text.startsWith('```')) {
        text = text.slice(3)
      }
      if (text.endsWith('```')) {
        text = text.slice(0, -3)
      }
      text = text.trim()

      const data = JSON.parse(text) as T
      return {
        id: response.id,
        data,
        status: response.status,
      }
    } catch (error) {
      // Log truncated response for debugging
      const preview = response.text.slice(0, 500)
      throw new Error(`Failed to parse structured response (possibly truncated). Preview: ${preview}...`)
    }
  }

  /**
   * Use Deep Research agent for comprehensive research tasks
   */
  async deepResearch(
    query: string,
    options: {
      pollIntervalMs?: number
      maxWaitMs?: number
      onProgress?: (status: string) => void
    } = {}
  ): Promise<GeminiResponse> {
    const initialInteraction = await this.createInteraction(query, {
      agent: 'deep-research-pro-preview-12-2025',
      background: true,
    })

    return this.pollForCompletion(initialInteraction.id, options)
  }

  /**
   * Create interaction with Google Search grounding
   */
  async createGroundedInteraction(
    input: string,
    options: Omit<InteractionOptions, 'tools'> = {}
  ): Promise<GeminiResponse> {
    return this.createInteraction(input, {
      ...options,
      tools: [{ type: 'google_search' }],
    })
  }

  /**
   * Create interaction with code execution capability
   */
  async createCodeExecutionInteraction(
    input: string,
    options: Omit<InteractionOptions, 'tools'> = {}
  ): Promise<GeminiResponse> {
    return this.createInteraction(input, {
      ...options,
      tools: [{ type: 'code_execution' }],
    })
  }

  private mapInteractionToResponse(interaction: Interaction): GeminiResponse {
    const outputs = (interaction as any).outputs || []
    let text = ''
    const functionCalls: FunctionCall[] = []

    for (const output of outputs) {
      if (output.type === 'text') {
        text = output.text || ''
      } else if (output.type === 'function_call') {
        functionCalls.push({
          id: output.id,
          name: output.name,
          arguments: output.arguments,
        })
      }
    }

    const usage = (interaction as any).usage

    return {
      id: (interaction as any).id,
      text,
      status: (interaction as any).status || 'completed',
      functionCalls: functionCalls.length > 0 ? functionCalls : undefined,
      usage: usage ? {
        promptTokens: usage.prompt_tokens || 0,
        completionTokens: usage.completion_tokens || 0,
        totalTokens: usage.total_tokens || 0,
      } : undefined,
    }
  }

  private sleep(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms))
  }
}

